const D = { energy: .62, density: .55, scale: 1, speed: 1, warp: .5, layers: 3, hue: 210, x: .5, y: .5, style: 'neon', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
if (S.seedUsed !== P.seed || !S.L) {
  S.seedUsed = P.seed;
  S.L = [];
  for (let l = 0; l < 4; l++) {
    S.L.push({
      nBase: 5 + Math.floor(fr(l * 7 + 1) * 7),   // 5..11 turtle segments
      sym: 4 + Math.floor(fr(l * 7 + 2) * 5),      // 4..8 rotational copies
      k: 1 + Math.floor(fr(l * 7 + 3) * 4),        // angle numerator
      hoff: fr(l * 7 + 4),                          // hue spread seed
      dir: fr(l * 7 + 5) < .5 ? -1 : 1,            // spin direction
      ph: fr(l * 7 + 6) * 6.283,                    // phase offset
      wf: .25 + fr(l * 7 + 7) * .5                  // breathe frequency
    });
  }
}

const u = Math.min(width, height);
const cx = width * P.x, cy = height * P.y;
const nLayers = Math.max(1, Math.min(4, Math.round(P.layers)));
const section = K.section | 0;
const t = K.t;
const af = P.alpha / 100;
const expo = .5 + P.energy * .9 + K.intensity * .3 + A.bass * .6;
const style = P.style;

// ---- style discipline table ----
let addMode = true, closeShape = true;
let gH = (P.hue + 200) % 360, gS = 55, gB = 9;    // ground
let bloomH = P.hue, satBase = 82, coreShift = 18, coreSat = 55;
let blendAlpha = 60, weightVary = 0, hueSpread = 300;
if (style === 'gold') {
  gH = 34; gS = 78; gB = 5; bloomH = 42; satBase = 86; coreShift = 8; coreSat = 40; hueSpread = 40;
} else if (style === 'blueprint') {
  addMode = false; gH = 212; gS = 78; gB = 24; satBase = 14; blendAlpha = 78; hueSpread = 24; weightVary = 0;
} else if (style === 'pastel') {
  addMode = false; gH = P.hue; gS = 20; gB = 22; satBase = 36; blendAlpha = 30; hueSpread = 260; weightVary = 0;
} else if (style === 'ink') {
  addMode = false; gH = 42; gS = 10; gB = 92; satBase = 28; blendAlpha = 60; hueSpread = 30; weightVary = 1; closeShape = true;
}

push();
if (P.alpha >= 100) background(gH, gS, gB);

// soft radial bloom to lift luminance + fill frame (additive styles)
if (addMode) {
  blendMode(ADD); noStroke();
  const bl = (5 + P.energy * 9 + K.intensity * 4) * af;
  for (let b = 0; b < 3; b++) {
    fill((bloomH + section * 14 + b * 10) % 360, 45, 85, bl);
    ellipse(cx, cy, u * (0.55 + b * 0.4), u * (0.55 + b * 0.4));
  }
}

translate(cx, cy);
const wCore = Math.max(1, u * 0.0022 * (0.6 + P.energy) * P.scale);
const wWide = u * (0.006 + P.energy * 0.010) * P.scale + (addMode ? A.bass * u * 0.01 : 0);

for (let l = 0; l < nLayers; l++) {
  const cfg = S.L[l];
  const N = Math.max(3, Math.min(18, Math.round(cfg.nBase * (0.6 + P.density * 1.0))));
  const m = Math.max(3, Math.min(10, Math.round(cfg.sym * (0.7 + P.density * 0.5)) + (section > 3 ? 1 : 0)));
  const drift = t * 6 * P.speed * cfg.dir;                       // perpetual morph (deg)
  const breathe = Math.sin(t * cfg.wf + cfg.ph) * 22 * P.warp;   // angle wobble
  const thetaR = (360 * cfg.k / N + drift + breathe) * Math.PI / 180;

  // turtle walk: segment i has length i, turn thetaR each step
  const xs = [0], ys = [0];
  let x = 0, y = 0, a = cfg.ph;
  for (let i = 1; i <= N; i++) { a += thetaR; x += Math.cos(a) * i; y += Math.sin(a) * i; xs.push(x); ys.push(y); }
  const len = xs.length;
  let mx = 0, my = 0; for (let i = 0; i < len; i++) { mx += xs[i]; my += ys[i]; } mx /= len; my /= len;
  let maxR = 1e-4; for (let i = 0; i < len; i++) { const dx = xs[i] - mx, dy = ys[i] - my; const r = Math.sqrt(dx * dx + dy * dy); if (r > maxR) maxR = r; }
  const fit = (0.47 * u * P.scale) / maxR;

  const rotSpeed = t * 0.12 * P.speed * cfg.dir;
  const hue = (P.hue + section * 16 + cfg.hoff * 60 + l * (hueSpread / nLayers)) % 360;
  const wideA = Math.min(60, (7 + P.energy * 13) * af * (0.55 + P.density * 0.55));
  const coreA = Math.min(95, (34 + P.energy * 46 + A.treble * 28) * af);

  noFill();
  for (let c = 0; c < m; c++) {
    const rot = rotSpeed + c * (6.28318 / m) + cfg.ph * 0.3;
    push();
    rotate(rot);
    if (addMode) {
      blendMode(ADD);
      stroke(hue, satBase, 100, wideA); strokeWeight(wWide);
      drawPoly(xs, ys, mx, my, fit, closeShape);
      stroke((hue + coreShift) % 360, coreSat, 100, coreA); strokeWeight(wCore);
      drawPoly(xs, ys, mx, my, fit, closeShape);
    } else {
      blendMode(BLEND);
      const wv = weightVary ? (0.55 + ((c + l) % 3) * 0.55) : 1;
      const sB = style === 'blueprint' ? 100 : (style === 'pastel' ? 96 : 18);
      stroke(hue, satBase, sB, blendAlpha * af);
      strokeWeight(style === 'blueprint' ? wCore * 1.1 : (style === 'pastel' ? wWide * 1.6 : wWide * wv));
      drawPoly(xs, ys, mx, my, fit, closeShape);
    }
    pop();
  }
}
blendMode(BLEND);
pop();

function drawPoly(xs, ys, mx, my, fit, close) {
  beginShape();
  for (let i = 0; i < xs.length; i++) vertex((xs[i] - mx) * fit, (ys[i] - my) * fit);
  endShape(close ? CLOSE : undefined);
}
